// --- Transport ---

/** Per-operation transport options. The generator threads these straight
 * through to `Transport.request` without inspecting them, so concrete
 * transports can layer in framework-specific knobs (e.g. axios's
 * `skipErrorPopup`) without the codegen having to know about them.
 */
export interface TransportOptions {
  [key: string]: unknown
}

export interface TransportRequest {
  /** Stable identifier for the operation issuing this request, of the form
   * `<ServiceClient>.<methodName>`. Middleware (e.g. tracing) can use this
   * to name a span or attach attributes; the underlying HTTP transport
   * ignores it.
   */
  operation: string
  method: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE'
  url: string
  query?: Record<string, string | number | boolean | undefined>
  headers?: Record<string, string>
  body?: unknown
  options?: TransportOptions
}

export interface TransportResponse {
  status: number
  body: unknown
  /** Lowercased header names → values. Concrete transports must lowercase
   * keys so the client's error-dispatch lookup is case-insensitive.
   */
  headers: Record<string, string>
}

export interface Transport {
  request(req: TransportRequest): Promise<TransportResponse>
}

/** Thrown when the server returned a non-2xx status the client couldn't
 * match against the operation's declared errors — either no error is
 * declared for that status, or `X-Error-Type` didn't name any of them.
 * 401s are converted to `UnauthenticatedError` by the transport before
 * the client sees them, so they don't surface here.
 */
export class UnexpectedResponseError extends Error {
  readonly operation: string
  readonly status: number
  readonly body: unknown
  readonly headers: Record<string, string>
  constructor(operation: string, status: number, body: unknown, headers: Record<string, string>) {
    super(operation + ' -> ' + status)
    this.name = 'UnexpectedResponseError'
    this.operation = operation
    this.status = status
    this.body = body
    this.headers = headers
  }
}

/** Thrown by the transport for any 401. The auth middleware sits in front
 * of every route and isn't modelled per-operation, so 401 is never in an
 * operation's `errors: [...]` — we surface it as a typed error here.
 */
export class UnauthenticatedError extends Error {
  readonly operation: string
  constructor(operation: string) {
    super(operation + ' -> 401 Unauthorized')
    this.name = 'UnauthenticatedError'
    this.operation = operation
  }
}


